          '**Two physical PCIe x16 slots do not guarantee two x16 electrical connections.** Many consumer motherboards wire the second slot at x4 electrical, even though it is physically x16-sized. For tensor-split LLM inference, both GPUs actively transfer data during every forward pass — a x4 second slot can become a real bottleneck, not a theoretical one.',
          'Before buying a motherboard, check its specification sheet for "PCIe lane allocation" or "x8/x8 mode" — this is usually listed explicitly for boards that support it, since it depends on the board splitting the CPU\'s PCIe lanes between the two GPU slots. This build assumes a B650 ATX board that explicitly lists x8/x8 support.',
