    intro: '**Una PC para LLM local con doble GPU, con dos tarjetas RTX 5060 Ti 16GB (32GB de VRAM combinada), un Ryzen 7 9700X y 64GB de RAM DDR5, cuesta unos $2,440 a los precios de EE. UU. de la lista de piezas (fuentes y fechas más abajo) y aloja un modelo de 32B en Q4 (unos 20GB según la biblioteca de Ollama) por completo en VRAM, con espacio para el contexto.** Un modelo de 70B en Q4 pesa unos 43GB, así que no cabe en 32GB: las capas restantes deben pasar a la RAM del sistema, algo que llama.cpp permite pero que es más lento y no se ha medido aquí. Esta guía cubre los componentes, el requisito de placa base que hace que la doble GPU funcione bien y qué cabe en 32GB. No da cifras de tokens por segundo porque este build no se ha evaluado.',
