    leadAnswerBlock: '**Un build de PC para LLM local con doble GPU cuesta unos $2,440 y ofrece 32GB de VRAM combinada, suficiente para alojar un modelo de 32B en Q4 (unos 20GB) por completo en las GPUs. Dos RTX 5060 Ti 16GB (unos $679 cada una, $1,358 en total) se combinan con un Ryzen 7 9700X ($330), 64GB DDR5-6000 ($180), un SSD NVMe Gen4 de 2TB ($130), una placa B650 ATX con ranuras PCIe x8/x8 ($180), una fuente 850W 80+ Gold ($130), una caja ATX ($90) y un disipador de aire ($40). Un modelo de 70B en Q4 pesa unos 43GB y no cabe en 32GB sin pasar capas a la RAM del sistema; las velocidades de este build no se han medido aquí.**',
