          '**La generación de PCIe importa menos que la cantidad de líneas** para esta carga de trabajo — PCIe 4.0 x8 normalmente excede lo que realmente necesita la transferencia con tensor-split; perseguir ranuras PCIe 5.0 no justifica el sobreprecio aquí.',
