          '**避けるべき：** 異なるGPUの組み合わせ（例：5060 Ti 1枚＋4060 Ti 1枚）— テンソル分割の性能は遅い方のカードに制限され、GPU世代を混在させるとドライバやサポート面で問題が生じることがあります。',
