    intro: '**Ein Dual-GPU-PC für lokale LLMs mit zwei RTX 5060 Ti 16GB (32 GB VRAM kombiniert), einem Ryzen 7 9700X und 64GB DDR5-RAM kostet zu den in der Teileliste genannten US-Preisen (Quellen und Datum dort) etwa 2.440 $ und hält ein 32B-Modell bei Q4 (laut Ollama-Bibliothek rund 20 GB) vollständig im VRAM, mit Platz für den Kontext.** Ein 70B-Modell bei Q4 umfasst rund 43 GB und passt daher nicht in 32 GB; die übrigen Layer müssen in den System-RAM ausgelagert werden, was llama.cpp unterstützt, aber langsamer ist und hier nicht gemessen wurde. Dieser Leitfaden behandelt die Komponenten, die Mainboard-Anforderung, die Dual-GPU-Betrieb erst richtig funktionieren lässt, und was in 32 GB passt. Tokens-pro-Sekunde-Werte nennt er nicht, weil dieser Build nicht per Benchmark gemessen wurde.',
