    leadAnswerBlock: '**Ein Dual-GPU-PC-Build für lokale LLMs kostet etwa 2.440 $ und bietet 32 GB kombinierten VRAM, genug, um ein 32B-Modell bei Q4 (rund 20 GB) komplett auf den GPUs zu halten. Zwei RTX 5060 Ti 16GB (ca. 679 $ pro Karte, zusammen 1.358 $) werden kombiniert mit einem Ryzen 7 9700X (330 $), 64GB DDR5-6000 (180 $), einer 2TB-Gen4-NVMe-SSD (130 $), einem B650-ATX-Board mit x8/x8-PCIe-Slots (180 $), einem 850W-80+-Gold-Netzteil (130 $), einem ATX-Gehäuse (90 $) und einem Luftkühler (40 $). Ein 70B-Modell bei Q4 umfasst rund 43 GB und passt ohne Auslagerung von Layern in den System-RAM nicht in 32 GB; Geschwindigkeiten dieses Builds wurden hier nicht gemessen.**',
