          '**Die PCIe-Generation spielt eine geringere Rolle als die Lane-Zahl** für diese Arbeitslast — PCIe 4.0 x8 übertrifft in der Regel, was Tensor-Split-Transfers tatsächlich brauchen; PCIe-5.0-Slots hinterherzujagen lohnt hier keinen Preisaufschlag.',
