          '**Auf eine Sättigung der PCIe-Bandbreite achten:** Wenn die Generierung unerwartet langsam ist, prüfen Sie, ob das Mainboard tatsächlich mit x8/x8 läuft und nicht unbemerkt auf x4 zurückfällt.',
