    intro: '**Un PC pour LLM local à double GPU, avec deux cartes RTX 5060 Ti 16 Go (32 Go de VRAM cumulée), un Ryzen 7 9700X et 64 Go de RAM DDR5, coûte environ $2,440 aux prix américains de la liste des composants (sources et dates ci-dessous) et loge un modèle 32B en Q4 (environ 20 Go selon la bibliothèque Ollama) entièrement en VRAM, avec de la marge pour le contexte.** Un modèle 70B en Q4 pèse environ 43 Go : il ne tient donc pas dans 32 Go, et les couches restantes doivent être déportées en RAM système, ce que llama.cpp permet mais plus lentement et sans mesure ici. Ce guide détaille les composants, l\'exigence de carte mère qui permet au double GPU de fonctionner correctement et ce qui tient dans 32 Go. Il ne donne aucun débit en tokens par seconde, car cette configuration n\'a pas été testée en benchmark.',
