          '**A geração do PCIe importa menos do que a quantidade de lanes** para essa carga de trabalho — PCIe 4.0 x8 normalmente excede o que a transferência do tensor-split realmente precisa; buscar slots PCIe 5.0 não vale um preço mais alto aqui.',
